/**
 * @param {number[][]} grid
 * @return {number}
 */
var closedIsland = function(grid) {
    let closedIslands = 0;

    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[i].length; j++) {
            if (isLand(grid, i, j) && isClosedIsland(grid, i, j)) {
                closedIslands++;
            }
        }
    }

    return closedIslands;
};

const isLand = (grid, i, j) => grid[i][j] === 0;

const isClosedIsland = (grid, i, j) => {
    const connectedLands = getConnectedLands(grid, i, j);
    return connectedLands.length > 0 &&
        connectedLands.every(([ i, j ]) => !isGridBorder(grid, i, j));
}

const getConnectedLands = (grid, i, j) => {
    if (isOutOfBounds(grid, i, j) || !isLand(grid, i, j)) {
        return [];
    }

    grid[i][j] = 2;

    const connectedLands = [
        [i + 1, j],
        [i, j - 1],
        [i, j + 1],
        [i - 1, j],
    ]
        .reduce((acc, [ i, j ]) => [
            ...acc,
            ...getConnectedLands(grid, i, j),
        ], []);

    return [
        [i, j],
        ...connectedLands,
    ];
}

const isOutOfBounds = (grid, i, j) =>
    i < 0 || i > grid.length - 1 ||
    j < 0 || j > grid[i].length - 1;

const isGridBorder = (grid, i, j) =>
    i === 0 || i === grid.length - 1 ||
    j === 0 || j === grid[i].length - 1;

/**
 * @param {number[][]} grid
 * @return {number}
 */
var closedIsland = function(grid) {
    const rows = grid.length;
    const cols = grid[0].length;

    const explore = (id, row, col) => {
        if (row < 0 || row >= rows || col < 0 || col >= cols) return false;
        if (grid[row][col] === 1 || grid[row][col] === id) return true;
        if (grid[row][col] !== 0) return false;

        grid[row][col] = id;

        const temp = explore(id, row, col + 1) &&
            explore(id, row + 1, col) &&
            explore(id, row, col - 1) &&
            explore(id, row - 1, col);

        if (!temp) {
            grid[row][col] = -1;
        }

        return temp;
    };

    let res = 0;

    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
            if (grid[row][col] === 0) {
                if (explore(res + 2, row, col)) {
                    res++;
                }
            }
        }
    }

    return res;
};
